import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

function Auth({ setToken }) {
  const [isRegister, setIsRegister] = useState(false); // ⚡ Login o Registro
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState(''); // ⚡ solo para registro
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  // Redirige automáticamente si ya hay token
  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) navigate('/products');
  }, [navigate]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const url = isRegister
        ? 'http://localhost/api/register'
        : 'http://localhost/api/login';

      const bodyData = isRegister
        ? { nom: name, email, password }
        : { login: email, password }; // ⚡ login para tu API

      const res = await fetch(url, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify(bodyData)
      });

      const data = await res.json();

      if (!res.ok || !data.exit) {
        setError(data.missatge || 'Error en les credencials');
      } else {
        if (!isRegister) {
          localStorage.setItem('token', data.token);
          if (setToken) setToken(data.token);
          navigate('/products');
        } else {
          // Registro exitoso: cambia a login automáticamente
          alert('Registre completat! Ara pots iniciar sessió.');
          setIsRegister(false);
          setName('');
          setEmail('');
          setPassword('');
        }
      }
    } catch (err) {
      console.error(err);
      setError('Error de connexió');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container mt-5">
      <h2>{isRegister ? 'Registrar-se' : 'Iniciar sessió'}</h2>

      <form onSubmit={handleSubmit}>
        {isRegister && (
          <div className="mb-3">
            <label>Nom</label>
            <input
              type="text"
              className="form-control"
              value={name}
              onChange={e => setName(e.target.value)}
              required
            />
          </div>
        )}

        <div className="mb-3">
          <label>Email</label>
          <input
            type="email"
            className="form-control"
            value={email}
            onChange={e => setEmail(e.target.value)}
            required
          />
        </div>

        <div className="mb-3">
          <label>Contrasenya</label>
          <input
            type="password"
            className="form-control"
            value={password}
            onChange={e => setPassword(e.target.value)}
            required
          />
        </div>

        {error && <p className="text-danger">{error}</p>}
        {loading && <p className="text-info">Carregant...</p>}

        <button type="submit" className="btn btn-primary" disabled={loading}>
          {isRegister ? 'Registrar' : 'Entrar'}
        </button>
      </form>

      <hr />
      <p>
        {isRegister
          ? 'Ja tens compte? '
          : 'No tens compte? '}
        <button
          className="btn btn-link p-0"
          onClick={() => {
            setIsRegister(!isRegister);
            setError('');
          }}
        >
          {isRegister ? 'Inicia sessió' : 'Registrar-se'}
        </button>
      </p>
    </div>
  );
}

export default Auth;
